fn solve(coins: Vec<i8>) -> i8 {
    // We assume `coins.len() == 5` and each coin is in 0..=100.
    // Sum can be up to 500, so accumulate in i32 to avoid overflow.
    let sum: i32 = coins.iter().map(|&c| c as i32).sum();
    // If the sum is strictly positive and divisible by 5, return the average.
    if sum > 0 && sum % 5 == 0 {
        (sum / 5) as i8
    } else {
        -1
    }
}

